#[ReturnTypeWillChange]
public static function __set_state($dump)
{
    /** @noinspection PhpVoidFunctionResultUsedInspection */
    /** @var DateInterval $dateInterval */
    $dateInterval = parent::__set_state($dump);

    return static::instance($dateInterval);
}

/**
 * Returns the values to dump on serialize() called on.
 *
 * @return array
 */
public function __serialize(): array
{
    $properties = [
        'interval' => parent::__serialize(),
    ];

    if ($this->localTranslator ?? null) {
        $properties['dumpLocale'] = $this->locale ?? null;
    }

    $reflection = new ReflectionObject($this);

    foreach ($reflection->getProperties() as $property) {
        if ($property->isStatic()) {
            continue;
        }

        $property->setAccessible(true);
        $name = $property->getName();

        if (\in_array($name, ['localTranslator', 'dumpLocale', 'step'], true)) {
            continue;
        }

        $value = $property->getValue($this);

        if ($value instanceof Closure) {
            continue;
        }

        $properties[$name] = $value;
    }

    return $properties;
}

/**
 * Restore the instance state from the values dumped by __serialize() and
 * support intervals serialized with Carbon 2.
 */
public function __unserialize(array $data): void
{
    // Intervals serialized with Carbon 2 stored the timezone in "tzName"
    if (isset($data['tzName'])) {
        $data['timezoneSetting'] = $data['tzName'];
        unset($data['tzName']);
    }

    if (isset($data['interval']) && \is_array($data['interval'])) {
        parent::__unserialize($data['interval']);
        unset($data['interval']);
    } else {
        // Legacy dumps have the DateInterval properties at the root of the data.
        $intervalProperties = [];

        foreach ($data as $key => $value) {
            if (\in_array($key, ['y', 'm', 'd', 'h', 'i', 's', 'f', 'invert', 'days', 'from_string'], true)) {
                $intervalProperties[$key] = $value;
                unset($data[$key]);
            }
        }

        parent::__unserialize($intervalProperties);
    }

    foreach ($data as $name => $value) {
        if ($name === 'dumpLocale' || !\property_exists($this, $name)) {
            continue;
        }

        $this->$name = $value;
    }

    if (isset($data['dumpLocale'])) {
        $this->locale($data['dumpLocale']);
    }
}

